const refGlyphSize = 28.0

func measureText(text string, size int) float64 {
	scale := float64(size) / refGlyphSize
	var total float64
	for _, r := range text {
		g, ok := builtInGlyphs[r]
		if !ok {
			g = builtInGlyphs['?']
		}
		total += float64(g.advance) * scale
	}
	return total
}

func drawGlyph(dst *image.NRGBA, r rune, startX, startY float64, size int, fillColor, strokeColor color.NRGBA, strokeWidth int) float64 {
	g, ok := builtInGlyphs[r]
	if !ok {
		g = builtInGlyphs['?']
	}
	scale := float64(size) / refGlyphSize
	bounds := dst.Bounds()

	// 1. If strokeWidth > 0, draw stroke first
	if strokeWidth > 0 && strokeColor.A > 0 {
		for row := 0; row < 34; row++ {
			bits := g.rows[row]
			if bits == 0 {
				continue
			}
			y0 := int(math.Round(startY + float64(row)*scale))
			y1 := int(math.Round(startY + float64(row+1)*scale))
			if y1 <= y0 {
				y1 = y0 + 1
			}
			for col := 0; col < int(g.width); col++ {
				if (bits & (1 << col)) != 0 {
					x0 := int(math.Round(startX + float64(col)*scale))
					x1 := int(math.Round(startX + float64(col+1)*scale))
					if x1 <= x0 {
						x1 = x0 + 1
					}
					for py := y0 - strokeWidth; py < y1+strokeWidth; py++ {
						if py < bounds.Min.Y || py >= bounds.Max.Y {
							continue
						}
						for px := x0 - strokeWidth; px < x1+strokeWidth; px++ {
							if px < bounds.Min.X || px >= bounds.Max.X {
								continue
							}
							dst.SetNRGBA(px, py, strokeColor)
						}
					}
				}
			}
		}
	}

	// 2. Draw fill over stroke
	if fillColor.A > 0 {
		for row := 0; row < 34; row++ {
			bits := g.rows[row]
			if bits == 0 {
				continue
			}
			y0 := int(math.Round(startY + float64(row)*scale))
			y1 := int(math.Round(startY + float64(row+1)*scale))
			if y1 <= y0 {
				y1 = y0 + 1
			}
			for col := 0; col < int(g.width); col++ {
				if (bits & (1 << col)) != 0 {
					x0 := int(math.Round(startX + float64(col)*scale))
					x1 := int(math.Round(startX + float64(col+1)*scale))
					if x1 <= x0 {
						x1 = x0 + 1
					}
					for py := y0; py < y1; py++ {
						if py < bounds.Min.Y || py >= bounds.Max.Y {
							continue
						}
						for px := x0; px < x1; px++ {
							if px < bounds.Min.X || px >= bounds.Max.X {
								continue
							}
							dst.SetNRGBA(px, py, fillColor)
						}
					}
				}
			}
		}
	}

	return float64(g.advance) * scale
}

func drawString(dst *image.NRGBA, text string, startX, startY float64, size int, fillColor, strokeColor color.NRGBA, strokeWidth int) float64 {
	curX := startX
	for _, r := range text {
		curX += drawGlyph(dst, r, curX, startY, size, fillColor, strokeColor, strokeWidth)
	}
	return curX - startX
}
